"use client";

import { useRef } from "react";
import gsap from "gsap";
import { useGSAP } from "@gsap/react";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import Link from "next/link";

if (typeof window !== "undefined") {
  gsap.registerPlugin(ScrollTrigger);
}

export function HeroSection() {
  const container = useRef<HTMLDivElement>(null);
  const text1 = useRef<HTMLDivElement>(null);
  const text2 = useRef<HTMLDivElement>(null);
  const bgImg = useRef<HTMLImageElement>(null);
  const content = useRef<HTMLDivElement>(null);

  useGSAP(() => {
    // Initial load animation
    const tl = gsap.timeline();
    tl.fromTo(bgImg.current, 
      { scale: 1.15, filter: "blur(20px)", opacity: 0 },
      { scale: 1, filter: "blur(0px)", opacity: 0.3, duration: 2, ease: "power3.out" }
    )
    .fromTo([text1.current, text2.current], 
      { y: 150, opacity: 0, rotation: 2, clipPath: "inset(100% 0% 0% 0%)" },
      { y: 0, opacity: 1, rotation: 0, clipPath: "inset(-20% 0% -20% 0%)", duration: 1.4, stagger: 0.15, ease: "power4.out" },
      "-=1.5"
    )
    .fromTo(content.current,
      { y: 30, opacity: 0 },
      { y: 0, opacity: 1, duration: 1, ease: "power3.out" },
      "-=1.0"
    );

    // Parallax & Scrub on Scroll
    gsap.to(bgImg.current, {
      yPercent: 30,
      scale: 1.1,
      ease: "none",
      scrollTrigger: {
        trigger: container.current,
        start: "top top",
        end: "bottom top",
        scrub: true,
      },
    });

    gsap.to([text1.current, text2.current, content.current], {
      yPercent: -40,
      opacity: 0,
      ease: "none",
      scrollTrigger: {
        trigger: container.current,
        start: "top top",
        end: "bottom top",
        scrub: true,
      },
    });

  }, { scope: container });

  return (
    <section ref={container} className="relative h-[100dvh] min-h-[700px] w-full flex flex-col items-center justify-center overflow-hidden bg-background border-b border-border">
      <div className="absolute inset-0 z-0">
        <img 
          ref={bgImg}
          src="/assets/hero.jpg" 
          className="w-full h-full object-cover mix-blend-multiply dark:mix-blend-screen opacity-0" 
          alt="Hero Architecture" 
        />
        <div className="absolute inset-0 bg-gradient-to-t from-background via-background/40 to-background/10 pointer-events-none" />
      </div>
      
      <div className="relative z-10 w-full max-w-[1400px] px-6 flex flex-col items-center text-center mt-12">
        <span className="text-[11px] font-medium uppercase tracking-[0.2em] text-primary mb-8 block opacity-80">The Ecosystem</span>
        
        <h1 className="font-display text-[clamp(4rem,9vw,11rem)] leading-[0.85] tracking-tight text-foreground mb-4 select-none">
          <div className="overflow-hidden py-2 px-4">
            <div ref={text1} className="origin-bottom-left">STRATEGIC</div>
          </div>
          <div className="overflow-hidden py-2 px-4 flex flex-col md:flex-row items-center justify-center gap-4 md:gap-8">
            <span className="hidden md:inline-block w-[18vw] max-w-[200px] h-[8vw] max-h-[90px] rounded-full bg-cover bg-center grayscale transition-all duration-700 hover:grayscale-0 hover:scale-105 shadow-2xl border border-border" style={{backgroundImage: "url('/assets/about-culture.jpg')"}}></span>
            <div ref={text2} className="font-display-italic text-primary origin-bottom-left">VENTURES.</div>
          </div>
        </h1>
        
        <div ref={content} className="flex flex-col items-center">
          <p className="text-muted-foreground text-lg md:text-xl max-w-2xl mx-auto font-light leading-relaxed mt-8 mb-12">
            Consulting, coaching, media, and education working in synergy to accelerate business transformation and unlock human potential.
          </p>
          
          <div className="flex flex-col sm:flex-row gap-6">
            <Link href="#group" className="inline-flex items-center justify-center px-8 py-4 bg-primary text-primary-foreground text-xs font-medium uppercase tracking-widest rounded-full hover:bg-foreground hover:text-background transition-all duration-300">
              Explore Our Group
            </Link>
            <Link href="/about" className="inline-flex items-center justify-center px-8 py-4 bg-transparent border border-border text-foreground text-xs font-medium uppercase tracking-widest rounded-full hover:border-foreground transition-all duration-300 hover:bg-foreground/5">
              Our Vision
            </Link>
          </div>
        </div>
      </div>
    </section>
  );
}
